        for j in range(W):
            if new_grid[i][j] == 'o':
                new_grid[i][j] = '.'
                removed = True
                break
        if removed:
            break
    if removed:
        new_input = f'{H} {W}\n' + '\n'.join(''.join(row) for row in new_grid)
        ans_orig = run(x).strip()
        ans_new = run(new_input).strip()
        # If both are integers, answer should not increase
        if ans_orig != '-1' and ans_new != '-1':
            assert int(ans_new) <= int(ans_orig)
        # If new is -1, original could be -1 or positive
        # No assertion needed"
    },
    {
      "name": "test_swap_rows_symmetric",
      "source": "def test_swap_rows_symmetric(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    if H < 2:
        return  # cannot swap
    grid = lines[1:]
    # Swap first two rows
    new_grid = [grid[1], grid[0]] + grid[2:]
    new_input = f'{H} {W}\n' + '\n'.join(new_grid)
    ans_orig = run(x).strip()
    ans_new = run(new_input).strip()
    assert ans_orig == ans_new"
