      "name": "test_bound_answer_range",
      "source": "def test_bound_answer_range(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    grid = lines[1:]
    leaf_count = sum(row.count('o') for row in grid)
    out = run(x).strip()
    if out != '-1':
        ans = int(out)
        # Cannot remove more leaves than exist
        assert 0 <= ans <= leaf_count"
