      "source": "def test_positive_answer_certificate(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    grid = lines[1:]
    out = run(x).strip()
    if out != '-1':
        ans = int(out)
        # If ans > 0, there must be at least ans leaves
        leaf_count = sum(row.count('o') for row in grid)
        assert ans <= leaf_count
        # Additionally, ans must be at least 1 if S and T are in different row/col and there is any leaf?
