      "source": "def test_change_leaf_to_empty_monotonic(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    grid = lines[1:]
    # Find an 'o' leaf, turn it into '.'
    new_grid = [list(row) for row in grid]
