    {
      "name": "test_minus_one_implies_connection",
      "source": "def test_minus_one_implies_connection(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    grid = lines[1:]
    out = run(x).strip()
    if out == '-1':
        # Then S and T must be in same row/col OR there is a path via leaves
        # We can check same row/col quickly
        S_pos = T_pos = None
        for i in range(H):
