                if grid[i][j] == 'S':
                    S_pos = (i, j)
                elif grid[i][j] == 'T':
                    T_pos = (i, j)
        if S_pos and T_pos:
            if S_pos[0] != T_pos[0] and S_pos[1] != T_pos[1]:
                # Not same row/col, so there must be a leaf path.
                # At least one leaf must exist? Not necessarily; but if no leaves, then impossible, which matches -1.
                # So we don't assert further.
                pass"
