def test_no_flights(run, x):
    n, m, k = map(int, x.split()[:3])
    if m == 0:
        out = run(x).strip()
        assert out == '-1', f'No flights ⇒ impossible, got {out}'


def test_only_inbound_or_only_outbound(run, x):
