    outbound = False
    for line in lines:
        if line.strip():
            d, f, t, c = map(int, line.split())
            if t == 0:
                inbound = True
            if f == 0:
                outbound = True
    if not inbound or not outbound:
        out = run(x).strip()
        assert out == '-1', f'Missing inbound/outbound flights ⇒ impossible, got {out}'


def test_cost_nonnegative(run, x):
    out = run(x).strip()
    if out != '-1':
        cost = int(out)
        assert cost >= 0, f'Cost {cost} must be non‑negative'


def test_cost_upper_bound(run, x):
    n, m, k = map(int, x.split()[:3])
    lines = x.strip().split('\n')[1:]
    min_in = [10**18] * (n+1)
    min_out = [10**18] * (n+1)
    for line in lines:
        if line.strip():
            d, f, t, c = map(int, line.split())
            if t == 0:          # inbound
                min_in[f] = min(min_in[f], c)
            if f == 0:          # outbound
                min_out[t] = min(min_out[t], c)
    sum_in = sum(v for v in min_in[1:] if v != 10**18)
    sum_out = sum(v for v in min_out[1:] if v != 10**18)
    max_possible = sum_in + sum_out if sum_in < 10**18*n and sum_out < 10**18*n else 10**18
    out = run(x).strip()
    if out != '-1':
        cost = int(out)
        assert cost <= max_possible, f'Cost {cost} exceeds trivial sum of minima {max_possible}'


