def test_cost_lower_bound_individual_mins(run, x):
    n, m, k = map(int, x.split()[:3])
    lines = x.strip().split('\n')[1:]
    min_in = [10**18] * (n+1)
    min_out = [10**18] * (n+1)
    for line in lines:
        if line.strip():
            d, f, t, c = map(int, line.split())
            if t == 0:
                min_in[f] = min(min_in[f], c)
            if f == 0:
                min_out[t] = min(min_out[t], c)
    lower = 0
    for city in range(1, n+1):
        if min_in[city] == 10**18 or min_out[city] == 10**18:
