def test_scaling_costs(run, x):
    n, m, k = map(int, x.split()[:3])
    lines = x.strip().split('\n')[1:]
    if m == 0:
        return
    # scale every cost by factor 2
    scaled_lines = []
    for line in lines:
        if line.strip():
            d, f, t, c = map(int, line.split())
            scaled_lines.append(f'{d} {f} {t} {2*c}')
    scaled_input = f'{n} {m} {k}\n' + '\n'.join(scaled_lines)
    out1 = run(x).strip()
    out2 = run(scaled_input).strip()
    if out1 == '-1':
        assert out2 == '-1', 'Impossible stays impossible after scaling'
    else:
        assert int(out2) == 2 * int(out1), f'Scaling costs by 2 should double total: {out1} → {out2}'


def test_adding_zero_cost_flights(run, x):
    n, m, k = map(int, x.split()[:3])
    lines = x.strip().split('\n')[1:]
    # find a city missing inbound or outbound
    inbound_seen = set()
    outbound_seen = set()
    for line in lines:
        if line.strip():
            d, f, t, c = map(int, line.split())
            if t == 0:
                inbound_seen.add(f)
            if f == 0:
                outbound_seen.add(t)
    missing_city = None
    for city in range(1, n+1):
        if city not in inbound_seen or city not in outbound_seen:
            missing_city = city
            break
    if missing_city is None or m >= 10**5 - 2:
        return  # all cities already have both flights, or would exceed m limit
    # add zero‑cost inbound and outbound on day 1 and day (10**6)
    new_lines = list(lines)
    new_lines.append(f'1 {missing_city} 0 0')
    new_lines.append(f'1000000 0 {missing_city} 0')
    new_input = f'{n} {m+2} {k}\n' + '\n'.join(new_lines)
    out_orig = run(x).strip()
    out_new = run(new_input).strip()
    if out_orig == '-1':
        # after adding zero‑cost flights it may become possible, so we cannot assert equality
        pass
    else:
        # adding zero‑cost flights must not increase total cost
        assert int(out_new) <= int(out_orig), f'Adding zero‑cost flights increased cost: {out_orig} → {out_new}'


def test_permute_cities(run, x):
    n, m, k = map(int, x.split()[:3])
    lines = x.strip().split('\n')[1:]
    # simple permutation: swap city 1 and 2 if n ≥ 2
    if n < 2:
        return
    perm = {0:0, 1:2, 2:1}
    perm_lines = []
    for line in lines:
        if line.strip():
            d, f, t, c = map(int, line.split())
            f2 = perm.get(f, f)
            t2 = perm.get(t, t)
            perm_lines.append(f'{d} {f2} {t2} {c}')
    perm_input = f'{n} {m} {k}\n' + '\n'.join(perm_lines)
    out1 = run(x).strip()
    out2 = run(perm_input).strip()
    assert out1 == out2, f'Permuting cities should not change total cost: {out1} vs {out2}'


