    val = int(out)
    assert val <= total_cost

def test_scaling_invariant(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if m == 0:
        return
    scaled_lines = [f"{n} {m} {k}"]
    for line in lines[1:1+m]:
        d, f, t, c = map(int, line.split())
        scaled_lines.append(f"{d} {f} {t} {c*2}")
    scaled_input = '\n'.join(scaled_lines)
    out1 = run(x).strip()
    out2 = run(scaled_input).strip()
    if out1 == '-1':
        assert out2 == '-1'
    else:
        assert int(out2) == 2 * int(out1)

