    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if n < 2 or m == 0:
        return
    # swap city 1 and 2 in all flights
    swapped_lines = [f"{n} {m} {k}"]
    for line in lines[1:1+m]:
        d, f, t, c = map(int, line.split())
        if f == 1:
            f = 2
        elif f == 2:
            f = 1
        if t == 1:
            t = 2
        elif t == 2:
            t = 1
        swapped_lines.append(f"{d} {f} {t} {c}")
    swapped_input = '\n'.join(swapped_lines)
    out1 = run(x).strip()
    out2 = run(swapped_input).strip()
    assert out1 == out2

