        assert val >= 0

def test_format(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if not lines:
        raise AssertionError('empty output')
    first = lines[0].strip()
    try:
        k = int(first)
    except ValueError:
        raise AssertionError('first line not integer')
    if len(lines) != k + 1:
        raise AssertionError('number of lines mismatch')
    suffixes = lines[1:]
    for suf in suffixes:
        if not (2 <= len(suf) <= 3):
            raise AssertionError('suffix length not 2 or 3')
    # also check no empty lines
    if any(s == '' for s in lines):
        raise AssertionError('empty line in output')

def test_suffix_substring(run, x):
