    if len(s) == 5:
        out = run(x)
        lines = out.strip().split('\n')
        k = int(lines[0])
        if k != 0:
            raise AssertionError('non-zero output for length 5')
        if len(lines) != 1:
            raise AssertionError('extra lines for length 5')

def test_suffix_lengths(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    suffixes = lines[1:]
    for suf in suffixes:
        if len(suf) != 2 and len(suf) != 3:
            raise AssertionError('suffix length invalid')

def test_no_empty_suffix(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    suffixes = lines[1:]
    if any(s == '' for s in suffixes):
        raise AssertionError('empty suffix')

def test_k_consistency(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if not lines:
        raise AssertionError('empty output')
    k = int(lines[0])
    suffixes = lines[1:]
    if len(suffixes) != k:
        raise AssertionError('k does not match number of suffixes')

def test_suffixes_in_tail(run, x):
    s = x.strip()
    tail = s[5:]
    out = run(x)
    lines = out.strip().split('\n')
    suffixes = lines[1:]
    for suf in suffixes:
        # check occurrence index >=5
        found = False
        for i in range(5, len(s) - len(suf) + 1):
            if s[i:i+len(suf)] == suf:
                found = True
                break
        if not found:
            raise AssertionError(f'suffix {suf} does not appear after index 4')

