def test_output_format(run, x):
    out = run(x).strip()
    if out == "Palindromic tree is better than splay tree":
        return
    n = int(out)
    assert n >= 0

def test_example_1_1(run, x):
    if x == "1 1\n":
        out = run(x).strip()
        assert out == "40"

def test_example_1_42(run, x):
    if x == "1 42\n":
        out = run(x).strip()
        assert out == "1"

def test_example_6_4(run, x):
    if x == "6 4\n":
        out = run(x).strip()
        assert out == "172"

def test_certificate_inequality_holds(run, x):
    out = run(x).strip()
    if out == "Palindromic tree is better than splay tree":
        return
    n = int(out)
    p_str, q_str = x.strip().split()
    p, q = int(p_str), int(q_str)
    A = p / q
    # compute pi(n) and rub(n) up to n
    lim = n
    sieve = [True] * (lim + 1)
    sieve[0:2] = [False, False]
    for i in range(2, int(lim**0.5)+1):
        if sieve[i]:
            for j in range(i*i, lim+1, i):
                sieve[j] = False
    pi_n = sum(1 for is_prime in sieve if is_prime)
    rub_n = sum(1 for i in range(1, n+1) if str(i) == str(i)[::-1])
    assert pi_n <= A * rub_n + 1e-12

def test_certificate_next_violates(run, x):
    out = run(x).strip()
    if out == "Palindromic tree is better than splay tree":
        return
    n = int(out)
    p_str, q_str = x.strip().split()
    p, q = int(p_str), int(q_str)
    A = p / q
    lim = n + 1
    sieve = [True] * (lim + 1)
    sieve[0:2] = [False, False]
    for i in range(2, int(lim**0.5)+1):
        if sieve[i]:
            for j in range(i*i, lim+1, i):
                sieve[j] = False
    pi_next = sum(1 for is_prime in sieve if is_prime)
    rub_next = sum(1 for i in range(1, lim+1) if str(i) == str(i)[::-1])
    # n+1 may be beyond limit where no finite n exists, but if finite n returned, n+1 should violate
    if n + 1 <= 2000000:  # reasonable limit for computation
        assert pi_next > A * rub_next - 1e-12

def test_magic_string_if_no_solution(run, x):
    # If magic string printed, verify that for all n up to some bound, inequality fails?
    # Too heavy. Instead, for given inputs, we trust that if magic string appears, it's plausible.
    # We'll just ensure that if output is not magic, it's integer.
    out = run(x).strip()
    if out != "Palindromic tree is better than splay tree":
        int(out)  # should not raise

def test_scaling_invariance(run, x):
    p_str, q_str = x.strip().split()
    p, q = int(p_str), int(q_str)
    # scale by 2, but ensure p*2, q*2 <= 10000
    if p * 2 <= 10000 and q * 2 <= 10000:
        scaled_input = f"{p*2} {q*2}\n"
        out1 = run(x).strip()
        out2 = run(scaled_input).strip()
        assert out1 == out2

def test_large_A_finite(run, x):
    if x == "42 1\n":
        out = run(x).strip()
        # should be finite integer, not magic string
        assert out != "Palindromic tree is better than splay tree"
        n = int(out)
        assert n > 0

def test_small_A_small(run, x):
    if x == "1 10000\n":
        out = run(x).strip()
        # A tiny, rub grows slowly, so max n should be small
        # We'll just check it's not huge (>10^6) which would be implausible
        if out != "Palindromic tree is better than splay tree":
            n = int(out)
            assert n < 1000000

