def test_counts_sum_N2(run, x):
    out = run(x).strip()
    cnts = list(map(int, out.split()))
    lines = x.strip().split('\n')
    N = int(lines[0])
    assert len(cnts) == 3
    assert sum(cnts) == N * N

def test_counts_non_negative(run, x):
    out = run(x).strip()
    cnts = list(map(int, out.split()))
    assert all(c >= 0 for c in cnts)

def test_counts_integers(run, x):
    out = run(x).strip()
    parts = out.split()
    assert len(parts) == 3
    for p in parts:
        # Ensure parsable as int
        int(p)

def test_first_row_column_preserved(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    first_row = list(map(int, lines[1].split()))
    first_col = [int(lines[i]) for i in range(2, 2 + N - 1)] if N > 1 else []
    # In the matrix built by the code, these should match given inputs.
    # We cannot access matrix directly, but we can check that total counts
    # of 0,1,2 in first row + first column minus a_{1,1} counted twice
    # are accounted for in output.
    # Instead, compute counts from given first row/col and ensure they
    # are <= output counts.
    out = run(x).strip()
    cnts = list(map(int, out.split()))
    given_counts = [0,0,0]
    for v in first_row:
        given_counts[v] += 1
    for v in first_col:
        given_counts[v] += 1
    if N >= 1:
        given_counts[first_row[0]] -= 1  # a11 counted twice
    assert cnts[0] >= given_counts[0]
    assert cnts[1] >= given_counts[1]
    assert cnts[2] >= given_counts[2]

def test_mex_table_consistency_small(run, x):
    # For N <= 3, compute whole matrix naively and compare counts.
    lines = x.strip().split('\n')
    N = int(lines[0])
    if N > 3:
        return  # skip large N
    first_row = list(map(int, lines[1].split()))
    first_col = [int(lines[i]) for i in range(2, 2 + N - 1)] if N > 1 else []
    # Build matrix
    mat = [[0]*N for _ in range(N)]
    for j in range(N):
        mat[0][j] = first_row[j]
    for i in range(1, N):
        mat[i][0] = first_col[i-1]
    def mex(x,y):
        if x == 0 and y == 0:
            return 1
        if x == 0 and y == 1:
            return 2
        if x == 0 and y == 2:
            return 1
        if x == 1 and y == 0:
            return 2
        if x == 1 and y == 1:
            return 0
        if x == 1 and y == 2:
            return 0
        if x == 2 and y == 0:
            return 1
        if x == 2 and y == 1:
            return 0
        if x == 2 and y == 2:
            return 0
    for i in range(1, N):
        for j in range(1, N):
            mat[i][j] = mex(mat[i-1][j], mat[i][j-1])
    exp_counts = [0,0,0]
    for i in range(N):
        for j in range(N):
            exp_counts[mat[i][j]] += 1
    out = run(x).strip()
    cnts = list(map(int, out.split()))
    assert cnts == exp_counts

def test_manual_compute_first_two_rows(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    if N < 2:
        return
    first_row = list(map(int, lines[1].split()))
    first_col = [int(lines[i]) for i in range(2, 2 + N - 1)]
    # Compute second row using mex
    def mex(x,y):
        if x == 0 and y == 0:
            return 1
        if x == 0 and y == 1:
            return 2
        if x == 0 and y == 2:
            return 1
        if x == 1 and y == 0:
            return 2
        if x == 1 and y == 1:
            return 0
        if x == 1 and y == 2:
            return 0
        if x == 2 and y == 0:
            return 1
        if x == 2 and y == 1:
            return 0
        if x == 2 and y == 2:
            return 0
    second_row = [first_col[0]]  # a_{2,0}
    for j in range(1, N):
        second_row.append(mex(first_row[j], second_row[j-1]))
    # Count first two rows from output
    out = run(x).strip()
    cnts = list(map(int, out.split()))
    # We can only check that counts for first two rows are <= total
    # Instead, verify that for each cell in second row, mex condition holds
    # with cell above and left? Already satisfied by construction.
    # Actually, we can verify that the second row computed matches the
    # second row that would be produced by a correct algorithm.
    # The output doesn't give per-cell, but we can check that total counts
    # for first two rows are at least counts of values we computed.
    first_two_counts = [0,0,0]
    for v in first_row:
        first_two_counts[v] += 1
    for v in second_row:
        first_two_counts[v] += 1
    # adjust duplicate a_{1,1}? No, we want union.
    # So total counts must be at least these.
    assert cnts[0] >= first_two_counts[0]
    assert cnts[1] >= first_two_counts[1]
    assert cnts[2] >= first_two_counts[2]

def test_mex_symmetry_check(run, x):
    # For any i,j >=2, mex(a,b) should be consistent with table.
    # We can check for i,j up to 3 using computed values.
    lines = x.strip().split('\n')
    N = int(lines[0])
    if N < 2:
        return
    first_row = list(map(int, lines[1].split()))
    first_col = [int(lines[i]) for i in range(2, 2 + N - 1)]
    # Build 3x3 top-left submatrix
    def mex(x,y):
        if x == 0 and y == 0:
            return 1
        if x == 0 and y == 1:
            return 2
        if x == 0 and y == 2:
            return 1
        if x == 1 and y == 0:
            return 2
        if x == 1 and y == 1:
            return 0
        if x == 1 and y == 2:
            return 0
        if x == 2 and y == 0:
            return 1
        if x == 2 and y == 1:
            return 0
        if x == 2 and y == 2:
            return 0
    sub = [[0]*3 for _ in range(3)]
    for j in range(3):
        if j < N:
            sub[0][j] = first_row[j]
        else:
            break
    for i in range(1,3):
        if i < N:
            sub[i][0] = first_col[i-1]
        else:
            break
    for i in range(1,3):
        for j in range(1,3):
            if i < N and j < N:
                sub[i][j] = mex(sub[i-1][j], sub[i][j-1])
    # Now verify mex condition for cell (2,2) if exists
    if N >= 3:
