def test_certify_by_small_region(run, x):
    # Compute first 10 rows and first 10 columns (or up to N) and verify
    # that the mex recurrence holds for i,j <=10. Then count those cells
    # and ensure the output counts are at least those counts.
    lines = x.strip().split('\n')
    N = int(lines[0])
    K = min(10, N)
    if K == 0:
        return
    first_row = list(map(int, lines[1].split()))
    first_col = [int(lines[i]) for i in range(2, 2 + N - 1)] if N > 1 else []
    def mex(x,y):
        if x == 0 and y == 0:
            return 1
        if x == 0 and y == 1:
            return 2
        if x == 0 and y == 2:
            return 1
        if x == 1 and y == 0:
            return 2
        if x == 1 and y == 1:
            return 0
        if x == 1 and y == 2:
            return 0
        if x == 2 and y == 0:
            return 1
        if x == 2 and y == 1:
            return 0
        if x == 2 and y == 2:
            return 0
    # Build KxK submatrix
    sub = [[0]*K for _ in range(K)]
    for j in range(K):
        sub[0][j] = first_row[j]
    for i in range(1, K):
        sub[i][0] = first_col[i-1]
    for i in range(1, K):
        for j in range(1, K):
            sub[i][j] = mex(sub[i-1][j], sub[i][j-1])
    # Count in submatrix
    sub_counts = [0,0,0]
    for i in range(K):
        for j in range(K):
            sub_counts[sub[i][j]] += 1
    out = run(x).strip()
    cnts = list(map(int, out.split()))
    # Total counts must be at least sub_counts
    assert cnts[0] >= sub_counts[0]
    assert cnts[1] >= sub_counts[1]
    assert cnts[2] >= sub_counts[2]

