        assert 0 <= val < MOD

def test_symmetry(run, x):
    K, N = map(int, x.strip().split())
    out = list(map(int, run(x).strip().split()))
    # For each i=2..2K, answer for i should equal answer for 2K+2-i
    # output[t] corresponds to i=t+1, t from 0..2K-2
    # So output[t] should equal output[2K-2 - t]
    for t in range(len(out)):
        assert out[t] == out[len(out)-1 - t], f'symmetry broken at positions {t} and {len(out)-1-t}'

